return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'uz_UZ','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Ushbu saytning media kutubxonasini Zinn® obyekt xotirasiga ko\'chiradi va uni CDN orqali taqdim etadi. Zinn® boshqaruv panelidan sozlangan — WordPress\'ga hech qanday kirish kaliti kiritilmaydi.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Saqlangan. Uni almashtirish uchun yangi qiymat kiriting.','Filter this list…'=>'Ushbu roʻyxatni filtrlash…','Filter this list'=>'Ushbu roʻyxatni filtrlash','Nothing matches that filter.'=>'Bu filtrga hech narsa mos kelmadi.','Add a row'=>'Qator qoʻshish','Remove this row'=>'Bu qatorni olib tashlash','Remove'=>'O‘chirish','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — umumiy koʻrinish','Overview'=>'Umumiy koʻrinish','Every Zinn® plugin on this site, and whether it is working.'=>'Ushbu saytdagi har bir Zinn® plagin va uning ishlayotgani.','No connection is needed for this plugin.'=>'Bu plagin uchun ulanish talab qilinmaydi.','Open settings'=>'Sozlamalarni ochish','You do not have permission to change these settings.'=>'Sizda bu sozlamalarni o\'zgartirish uchun ruxsat yo\'q.','Settings sections'=>'Sozlamalar bo\'limlari','Support'=>'Qo\'llab-quvvatlash','Save changes'=>'O‘zgarishlarni saqlash','Tools'=>'Vositalar','Export settings'=>'Sozlamalarni eksport qilish','Reset to defaults'=>'Standart holatga qaytarish','This puts every setting on this plugin back to its default. Continue?'=>'Bu ushbu plaginning barcha sozlamalarini standart holatiga qaytaradi. Davom etasizmi?','Diagnostics for support'=>'Qo\'llab-quvvatlash uchun diagnostika','Import a settings file'=>'Sozlamalar faylini import qilish','Import'=>'Import qilish','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Eksport qilingan fayllarda hech qachon parollar, tokenlar yoki API kalitlari bo\'lmaydi — ularni yangi saytda qaytadan kiritishingiz kerak bo\'ladi.','Settings saved.'=>'Sozlamalar saqlandi.','Every setting on this plugin is back to its default.'=>'Ushbu plaginning barcha sozlamalari o\'zining standart holatiga qaytarildi.','Done.'=>'Bajarildi.','That action is not available.'=>'Bu amal mavjud emas.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Bu faylni o‘qib bo‘lmadi. Zinn® plaginidan eksport qilingan sozlamalar faylini tanlang.','That file is too large to be a settings export.'=>'Bu fayl sozlamalar eksporti uchun juda katta.','That file is not a Zinn® settings export.'=>'Bu fayl Zinn® sozlamalari eksporti emas.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Bu fayl boshqa plagindan (%s) eksport qilingan, shuning uchun uni bu yerga import qilish ushbu plagin tushunmaydigan sozlamalarni saqlaydi.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d ta sozlama import qilindi. Parollar va API kalitlari eksportga kiritilmaydi, shuning uchun ularni qaytadan kiriting.' . "\0" . '%d ta sozlama import qilindi. Parollar va API kalitlari eksportga kiritilmaydi, shuning uchun ularni qaytadan kiriting.','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® token qaytargermadi. Bu saytda hech narsa o\'zgartirilmadi.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Bu sayt Zinn® media yuklab berish xizmatiga endi ulanmagan. Yangi yuklashlar ushbu serverda qoladi. Uni Zinn Digital® boshqaruv panelidan qaytadan juftlang.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® HTTP %d bilan javob berdi.','Disconnected by Zinn Digital®.'=>'Zinn Digital® tomonidan uzildi.','Connected'=>'Ulangan','Connecting…'=>'Ulanmoqda…','Connected, but something needs attention'=>'Ulandi, lekin e\'tibor talab qiladigan narsa bor','Not connected'=>'Ulanmagan','Running on your own account'=>'Oʻz hisobingizda ishlamoqda','We could not check this'=>'Buni tekshira olmadik','This plugin did not say why. Send a diagnostics report and we will look.'=>'Bu plagin nima sababdan ekanini aytmadi. Diagnostika hisobotini yuboring, biz ko\'rib chiqamiz.','Connection status'=>'Ulanish holati','Last checked %s ago.'=>'Oxirgi marta %s oldin tekshirilgan.','(opens in a new tab)'=>'(yangi tabda ochiladi)','Send this to Zinn® support'=>'Zinn® support\'ga yuborish','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Yuboriladigan narsa aynan shu — boshqa hech narsa va hech qanday yashirin ma\'lumot yo\'q. Parollaringiz, tokenlaringiz va API kalitlaringiz uning ichida emas.','The diagnostics report that will be sent'=>'Yuboriladigan diagnostika hisoboti','Copy to clipboard'=>'Buzraga nusxalash','Send this report to Zinn® support'=>'Ushbu hisobotni Zinn® qo\'llab-quvvatlash xizmatiga yuboring','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Biz siz uchun qo\'llab-quvvatlash so\'rovini ochamiz va elektron pochta orqali javob beramiz. Agar buni yuborishni istamasangiz, yuqoridagidan nusxa oling va uni o\'zingiz so\'rovga qo\'ying.','Copied'=>'Nusxa olindi','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Ushbu serverdan (%s) Zinn Digital® bilan bog‘lanib bo‘lmadi. Yuqoridagi hisobotni nusxalab oling va uning o‘rniga chekin oching — sozlamalaringizda hech qanday xato yo‘q.','Sent. Zinn® support has your report and will reply by email.'=>'Zinn® qo‘llab-quvvatlash xizmati hisobotingizni oldi va elektron pochta orqali javob beradi.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Sent. Zinn® yordam xizmati xabaringizni qabul qildi — ma\'lumotnoma %s — va elektron pochta orqali javob beradi.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Qisqa vaqt ichida bir nechta hisobot yubordingiz. Bir necha daqiqa kutib, qayta urinib ko\'ring — avvalgilari yetib kelgan.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® hozircha hisobotni qabul qila olmadi — bu bizning tomonda, siz tomonda emas. Qisqa vaqtdan keyin yana urinib ko‘ring yoki yuqoridagi hisobotni tiketga nusxalang.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Hisobot rad etildi (HTTP %d). Uni yuqoridan nusxalab oling va shu raqamni ko\'rsatgan holda murojaat oching.','%s — guides and services'=>'%s — qo\'llanmalar va xizmatlar','User guides'=>'Foydalanuvchi qoʻllanmalari','Read the %s user guide'=>'%s foydalanuvchi qo\'llanmasini o\'qing','Hide this'=>'Buni yashirish','Zinn® hosting for WordPress'=>'WordPress uchun Zinn® xostingi','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, kunlik zaxira nusxalari, bepul migratsiya va bittadan ortiq sayt yuritadiganlar uchun moʻljallangan boshqaruv paneli.','The Zinn® marketplace'=>'Zinn® bozori','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Tayyor saytlar, domenlar va havola joylashtirishni sotib oling va soting, ikkala tomon ham mamnun bo\'lgunga qadar pul xavfsiz tarzda saqlanadi.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — buni kasb qilgan mutaxassislarni yollang','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Bizning global frilanserlar bozori: matn yozuvchilar, dizaynerlar, dasturchilar va SEO mutaxassislarining 10 000 dan ortiq tayyor xizmatlarini ko\'rib chiqing yoki loyiha joylashtirib, ularga taklif kiritish imkonini bering.','Media Offload'=>'Media Offload','Connection'=>'Ulanish','What gets moved'=>'Nima ko\'chiriladi','How media is served'=>'Media qanday taqdim etiladi','Move a batch now'=>'Hozir bir qatorni ko\'chirish','Media already moved is never affected by a change here — its address does not change.'=>'Bu yerda kiritilgan o\'zgarishlar allaqochgan ko\'chirilgan mediaga ta\'sir qilmaydi — uning manzili o\'zgarmaydi.','New uploads'=>'Yangi yuklanganlar','Move new uploads to Zinn® storage as they arrive'=>'Yangi yuklangan fayllarni kelishi bilan Zinn® xotirasiga ko‘chirish','Existing media'=>'Mavjud media','Keep moving the media library that is already here'=>'Bu yerda allaqachon mavjud boʻlgan media kutubxonasini koʻchirishda davom eting','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'Orasiga to\'xtagan joyidan davom etib, fonda soatiga bir nechta fayl nusxalanadi. Buni o\'chirish jarayonni to\'xtatib turadi; allaqachon ko\'chirilgan hech narsa qaytarilmaydi.','Files per hourly pass'=>'Soatlik o‘tishdagi fayllar','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'Har bir biriktirma bir nechta fayldan iborat va ularning har biri toʻliq yuklash hisoblanadi. Buni yetarli bajarilish vaqtiga ega tezkor xostda oshiring; agar jarayonlar toʻxtatib qoʻyilayotgan boʻlsa, uni kamaytiring.','Leave files smaller than'=>'Quyidagidan kichik fayllarni qoldirish','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'Kilobayt. Kichkina belgi diskda tejaydigan joyidan ko\'ra qo\'shimcha ulanishda ko\'proq resurs talab qiladi, shuning uchun uni ko\'chirishga deyarli ehtiyoj yo\'q. Hammasini ko\'chirish uchun 0 qilib o\'rnating.','Never move these types'=>'Ushbu turlarni hech qachon ko\'chirmang','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'Plagin faylni to\'g\'ridan-to\'g\'ri diskdan o\'qiyotganda foydali — shrift, forma yaratuvchisi shtamplaydigan PDF, pleyer ichidan qidiradigan audio fayl.','These two are the ones to be careful with — read each description before changing it.'=>'Ushbu ikkitasiga e\'tibor berish lozim — har birini o\'zgartirishdan oldin tavsifini o\'qib chiqing.','Serve from Zinn® storage'=>'Zinn® xotirasidan xizmat ko‘rsatish','Point image and file addresses at Zinn® storage'=>'Rasm va fayl manzillarini Zinn® xotirasiga yo\'naltiring','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'O\'chiq, fayllar yuklangan, ammo baribir ushbu serverdan uzatilmoqda — hamma narsa kelib tushganini tekshirayotganingizda bu xavfsiz holat. Yoqilgan, tashrif buyuruvchilarga xotiradan xizmat ko\'rsatiladi va bu server trafikni uzatishni to\'xtatadi.','Free the disk space'=>'Disk maydonini bo\'shatish','Delete the local copy once every size has uploaded'=>'Har bir oʻlcham yuklangandan soʻng mahalliy nusxani oʻchirib tashlang','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'Bu offload qilish nuqtasi boʻlib, u shuningdek qaytarib boʻlmaydigan qismidir. “Serve from Zinn® storage” yoqilgunga va saytingizni tekshirib chiqquningizcha uni oʻchirmagan holda qoldiring — biror narsa eʼtibordan chetda qolgan taqdirda sizni faqat mahalliy nusxa saqlab qoladi.','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'Mahalliy nusxalarni oʻchirib tashlashni ushbu ekrandan turib ortga qaytarib boʻlmaydi. Avval zaxira nusxasini yarating — buning uchun Zinn® Connector plaginidan foydalanishingiz mumkin.','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'Bu sayt hali Zinn® xotirasiga ulanmagan, shuning uchun media fayllarni ko\'chirish uchun joy yo\'q.','%d attachment moved.'=>'%d ta ilova ko\'chirildi.' . "\0" . '%d ta biriktirma ko‘chirildi.','This site is not connected to Zinn® storage.'=>'Bu sayt Zinn® saqlash joyiga ulanmagan.','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'Hech qanday xatolik yo‘q — u shunchaki hali juftlashtirilmagan. Media fayllar shu holatga kelgunicha ushbu serverda qoladi.','Connected, but the last upload failed.'=>'Ulangan, lekin oxirgi yuklash muvaffaqiyatsiz tugadi.','Try a batch now'=>'Hozir to‘plamni sinab ko‘ring','Connected. Every attachment has been moved.'=>'Ulandi. Har bir ilova ko‘chirildi.','Connected. %1$s of %2$s attachments still on this server.'=>'Ulandi. %1$s ta %2$s biriktirma hali ham ushbu serverda qolmoqda.','Moved so far'=>'Ko\'chirilganlar','%1$s files, %2$s'=>'%1$s ta fayl, %2$s','Still on this server'=>'Hali ham ushbu serverda','%1$s of %2$s attachments'=>'%1$s / %2$s ta biriktirma','Served from'=>'Quyidagidan xizmat ko\'rsatilmoqda','this server'=>'ushbu server','Connect this site'=>'Ushbu saytni ulash','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'Zinn Digital® boshqaruv panelingizni oching, Xotira → Media offload bo‘limiga o‘ting va “Pair a site” tugmasini bosing. Quyidagi kodni joylashtiring.','Pairing code'=>'Juftlash kodi','Disconnect this site'=>'Bu saytni uzish','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'Yangi yuklangan fayllar ushbu serverda qoladi. Avval ko‘chirilgan media ishlashda davom etadi — uning manzili o‘zgarmaydi.','You do not have permission to manage this site.'=>'Ushbu saytni boshqarish uchun ruxsatingiz yo‘q.','Paste the pairing code from your Zinn Digital® dashboard.'=>'Zinn Digital® boshqaruv panelidan juftlashtirish kodini joylashtiring.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'Ulandi. Bundan buyon yangi yuklamalar Zinn Digital® da saqlanadi va mavjud medialaringiz fonda ko‘chiriladi.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'Uzilvdi. Oldindan ko‘chirilgan media fayllar ishlashda davom etadi; yangi yuklashlar ushbu serverda qoladi.','That file could not be read from this server, so nothing was uploaded.'=>'Bu faylni ushbu serverdan o\'qib bo\'lmadi, shuning uchun hech narsa yuklanmadi.','This site could not stream the upload, so nothing was sent.'=>'Bu sayt yuklangan faylni oqimlay olmadi, shuning uchun hech narsa yuborilmadi.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Bu fayl %1$s va bu sayt PHP\'sida cURL yo\'q, shuning uchun yuklab olinishi mumkin bo\'lgan eng katta hajm %2$s.','The upload could not be completed.'=>'Yuklash bajarilmadi.','Storage refused the upload (HTTP %d).'=>'Saqlaýchi yuklashni rad etdi (HTTP %d).','Style preset'=>'Uslub namunasi','A starting point. Anything below overrides it.'=>'Boshlang\'ich nuqta. Undan pastdagi har qanday narsa buni bekor qiladi.','Use my own colours and sizes'=>'O\'z ranglarim va o\'lchamlarimdan foydalanish','Leave this off and the preset is used exactly as it is.'=>'Buni o\'chirib qo\'ying va andoza o\'z holicha ishlatiladi.','See the Zinn Digital® release notes.'=>'Zinn Digital® chiqarilish eslatmalarini ko\'ring.','The downloaded update failed its integrity check and was not installed.'=>'Yuklab olingan yangilanish yaxlitlik tekshiruvidan o\'tmadi va o\'rnatilmadi.']];